/* Types */
/**
 *  Un compte de la liste d'administration. Les dates sont celles de l'agent (RFC 3339, UTC) ;
 *  l'interface les met en forme.
 */
export type AccountDto = {
	id: string,
	username: string,
	role: RoleDto,
	createdAt: string,
	lastLoginAt: string | null,
	sessionsOpen: number,
	/**
	 *  Le compte peut gérer les services (`rights` contient `"services"`, ADR-0041). Le client ne retient que
	 *  le droit qu'il connaît. En LECTURE SEULE : rien dans cette coquille n'accorde ni ne retire ce droit
	 *  (BR-GRANT-005).
	 */
	managesServices: boolean,
};

/**
 *  Verdict de la saisie en direct (`check_account_input`) : la règle est celle de `hearth-proto`,
 *  la même que celle de l'agent.
 */
export type AccountInputCheck = {
	username: UsernameProblemDto | null,
	password: PasswordRuleDto[],
};

/**
 *  La liste des comptes et qui est « moi » : l'identifiant de l'AGENT du compte de la session (jamais
 *  une comparaison de texte côté interface). Un refus de rôle de l'agent est `LinkFailure::Forbidden`
 *  (une seule façon de dire « accès refusé »).
 */
export type AccountListDto = {
	accounts: AccountDto[],
	me: string,
	/**
	 *  L'agent annonce la capacité `service-rights` : sans elle, `manages_services` est faux pour tous parce
	 *  que l'agent ne sait pas le dire, pas parce que personne ne l'a (BR-GRANT-016).
	 */
	rightsKnown: boolean,
};

/**  Issue d'une action de compte. */
export type AccountOutcome = 
/**
 *  L'agent a exécuté l'action. `account` : le compte créé ; `sessions_closed` : sessions
 *  fermées (0 si l'action n'en ferme pas).
 */
{ kind: "done"; account: AccountDto | null; sessions_closed: number } | { kind: "refused"; refusal: AccountRefusal } | 
/**
 *  Le lien est tombé avant la réponse : on ne sait pas, l'action n'est JAMAIS rejouée.
 *  L'issue arrive par `link://operation` sous cet identifiant ; la liste se relit au retour du
 *  lien.
 */
{ kind: "unknown"; op_id: string };

/**
 *  Pourquoi l'agent (ou la validation locale, avant tout envoi) a refusé. Sans texte : l'interface
 *  choisit le message d'après `kind`.
 */
export type AccountRefusal = 
/**  Identifiant au mauvais format : `problem` renseigné quand la validation locale l'a vu. */
{ kind: "invalid_username"; problem: UsernameProblemDto | null } | 
/**  Mot de passe refusé : toutes les règles non respectées. */
{ kind: "weak_password"; rules: PasswordRuleDto[] } | { kind: "username_taken" } | 
/**  Le mot de passe de confirmation (ou l'ancien mot de passe) est incorrect. */
{ kind: "wrong_password" } | 
/**
 *  L'élévation de 5 minutes s'est fermée côté agent et le mot de passe n'était pas dans la
 *  requête : la fenêtre le redemande, sans perdre la saisie de l'acte.
 */
{ kind: "password_required" } | 
/**  Trop d'essais de mot de passe : réessayer plus tard. */
{ kind: "too_many_attempts"; retry_after_s: number } | 
/**  Il doit toujours rester au moins un administrateur (BR-ACCT-007). */
{ kind: "last_admin" } | { kind: "not_found" } | 
/**  L'identifiant retapé pour supprimer son propre compte ne correspond pas (BR-ACCT-012). */
{ kind: "confirmation_mismatch" } | 
/**  Le mot de passe a changé entre la vérification et l'écriture : réessayer. */
{ kind: "conflict" } | 
/**  L'agent est saturé : réessayer dans un instant. */
{ kind: "busy" } | 
/**  La session a expiré pendant l'action : l'état du lien le dit. */
{ kind: "session_ended" } | 
/**  La session a été fermée (changement de mot de passe, suppression, révocation). */
{ kind: "session_revoked" } | { kind: "other" };

/**
 *  Ce que l'assistant envoie à sa dernière étape : le serveur confirmé et les identifiants. Pas de
 *  `Debug` : il porte un mot de passe.
 */
export type AddServerInput = {
	name: string,
	color: number,
	host: string,
	port: number | null,
	/**  Empreinte confirmée par l'utilisateur, forme complète : celle de la dernière sonde. */
	fingerprint: string,
	macAddresses: string[],
	username: string,
	password: string,
	remember: boolean,
};

/**  Le genre d'un acte d'administration, tel que la fenêtre le connaît (sans cible ni secret). */
export type AdminActKindDto = "account_create" | "account_role" | "account_password" | "account_delete" | "sessions_revoke" | "agent_update" | "attack_mode_enable" | "attack_mode_disable" | "account_password_own" | "reauth_setting";

/**  Qui a adopté un service, et quand (HRT-79). */
export type AdoptionDto = {
	by: string,
	at: string,
};

/**  Une version plus récente que l'agent est disponible (BR-UPDATE-022). Seulement son numéro. */
export type AgentAvailableDto = {
	version: string,
};

/**  Événement `agent-update://progress` : une progression reçue du flux d'un serveur. */
export type AgentUpdateEvent = {
	serverId: string,
	progress: AgentUpdateProgressDto,
};

/**  Issue de la demande de mise à jour de l'agent. */
export type AgentUpdateOutcome = 
/**  L'agent a accepté : la mise à jour s'exécute chez lui, l'avancement arrive par le flux. */
{ kind: "accepted"; version: string } | { kind: "refused"; refusal: AgentUpdateRefusal } | 
/**
 *  Le lien est tombé avant la réponse : on ne sait pas, la demande n'est JAMAIS rejouée.
 *  L'issue arrive par `link://operation` sous cet identifiant ; l'état se relit au retour du lien.
 */
{ kind: "unknown"; op_id: string };

export type AgentUpdateOutcomeDto = "succeeded" | "rolled_back" | "failed";

/**  Où en est la mise à jour en cours. */
export type AgentUpdateProgressDto = {
	version: string,
	step: AgentUpdateStepDto,
	/**  0 à 100, pour l'étape `download` seulement. */
	percent: number | null,
	/**  Pour l'étape `done` seulement. */
	outcome: AgentUpdateOutcomeDto | null,
	reason: AgentUpdateReasonDto | null,
};

/**
 *  Pourquoi une mise à jour n'a pas abouti. `Unknown` : une raison qu'un agent plus récent ajoute
 *  et que ce client ne connaît pas (jamais une erreur de lecture).
 */
export type AgentUpdateReasonDto = "unreachable" | "download_failed" | "bad_checksum" | "bad_signature" | "bad_binary" | "staging" | "swap" | "supervisor_launch" | "no_answer" | "identity_changed" | "interrupted" | "rollback_failed" | "unknown";

/**
 *  Pourquoi la demande n'a pas été acceptée. Sans texte : l'interface choisit le message d'après
 *  `kind`. Le refus de rôle de l'agent est `LinkFailure::Forbidden` (une seule façon de le dire).
 */
export type AgentUpdateRefusal = 
/**  Installation gérée par le système (ou sans systemd) : aucune mise à jour à distance. */
{ kind: "managed_install" } | 
/**  Une mise à jour est déjà en cours (BR-UPDATE-012). */
{ kind: "in_progress" } | 
/**  La signature de la cible est refusée par l'agent, avant tout téléchargement. */
{ kind: "bad_signature" } | 
/**  Un champ de la cible est refusé par l'agent (`version`, `url`, `sha256`, `signature`). */
{ kind: "invalid_target" } | 
/**  Le flux de versions ne propose aucune version à ce client (rien n'a été envoyé). */
{ kind: "no_target" } | 
/**
 *  La version que l'utilisateur a vue n'est plus celle que le client retient (rien n'a été
 *  envoyé) : relire l'état et confirmer de nouveau.
 */
{ kind: "target_changed" } | 
/**
 *  La version retenue n'est pas plus récente que l'agent (rien n'a été envoyé : jamais de
 *  rétrogradation).
 */
{ kind: "not_newer" } | 
/**  Le mot de passe de confirmation est faux (les compteurs de la connexion ont avancé). */
{ kind: "wrong_password" } | 
/**  L'élévation s'est fermée côté agent et le mot de passe n'était pas dans la requête. */
{ kind: "password_required" } | 
/**  Trop d'essais de mot de passe : réessayer plus tard. */
{ kind: "too_many_attempts"; retry_after_s: number } | 
/**  L'agent est saturé : réessayer dans un instant. */
{ kind: "busy" } | { kind: "other" };

/**  Le dernier résultat connu (survit au redémarrage de l'agent). */
export type AgentUpdateResultDto = {
	/**
	 *  La version visée ; `None` quand elle ne se sait pas (trace de travail illisible conclue au
	 *  démarrage) : le texte affiché n'a alors pas de numéro.
	 */
	version: string | null,
	previous: string,
	outcome: AgentUpdateOutcomeDto,
	reason: AgentUpdateReasonDto | null,
	/**  RFC 3339, UTC (celui de l'agent) : l'interface le met en forme. */
	at: string,
	/**
	 *  Le résultat date de moins de 24 h : il est annoncé comme un message (BR-UPDATE-017) ; plus
	 *  ancien, il n'est qu'une ligne d'historique. Décidé ici : l'interface ne calcule aucune date.
	 */
	recent: boolean,
	/**
	 *  Ce résultat (sa date `at`) a déjà été annoncé à l'utilisateur, par ce client ou avant son
	 *  dernier redémarrage : il ne l'est qu'une fois (`ack_agent_result`).
	 */
	announced: boolean,
};

export type AgentUpdateStepDto = "download" | "verify" | "install" | "restart" | "check" | "done";

/**  L'état de la mise à jour de l'agent d'un serveur, relu à la demande (affichage, retour du lien). */
export type AgentUpdateView = {
	/**  La version de l'agent qui répond (BR-UPDATE-022). */
	current: string,
	/**  Installation gérée par le système (ou sans systemd) : pas de mise à jour à distance. */
	managed: boolean,
	inProgress: boolean,
	progress: AgentUpdateProgressDto | null,
	last: AgentUpdateResultDto | null,
	/**
	 *  La version disponible dans le flux de versions, strictement plus récente que `current` ;
	 *  `None` si le flux n'en propose pas, ou si l'installation est gérée (aucun bouton à montrer).
	 */
	available: AgentAvailableDto | null,
};

/**  L'alerte « attaque probable » (BR-TRUST-008). */
export type AlertDto = {
	/**  L'identifiant du compte connecté est visé en ce moment. */
	own: boolean,
	/**  Début de l'épisode (RFC 3339, UTC), seulement quand `own`. */
	since: string | null,
	/**  Administrateur seulement : combien d'AUTRES comptes sont visés. */
	others: number | null,
};

/**
 *  Erreur d'une commande. Sérialisée `{ kind, message }` côté TypeScript ;
 *  l'interface choisit son texte d'après `kind`.
 */
export type AppError = 
/**  Lecture ou écriture des réglages locaux impossible. */
{ kind: "store"; message: string } | 
/**  Lecture ou écriture de l'entrée de démarrage de Windows impossible. */
{ kind: "autostart"; message: string } | 
/**  Dossier des journaux impossible à créer ou à ouvrir. */
{ kind: "logs"; message: string };

/**  Le mode attaque du serveur. */
export type AttackModeDto = {
	state: AttackModeStateDto,
	since: string | null,
	/**  Seulement « suspendu » : secondes avant la reprise. */
	resumesInS: number | null,
	lastEnd: AttackModeEndDto | null,
};

/**  Comment le dernier mode attaque s'est terminé. */
export type AttackModeEndDto = "manual" | "auto" | "cli";

/**  Issue d'une activation ou d'une désactivation. */
export type AttackModeOutcome = 
/**  L'agent a changé le mode (ou il l'était déjà) : l'état après le changement. */
{ kind: "done"; attack_mode: AttackModeDto } | { kind: "refused"; refusal: AttackModeRefusal } | 
/**
 *  Le lien est tombé avant la réponse : on ne sait pas, l'action n'est JAMAIS rejouée. L'issue
 *  arrive par `link://operation` sous cet identifiant ; l'état se relit au retour du lien.
 */
{ kind: "unknown"; op_id: string };

/**
 *  Pourquoi une activation ou une désactivation est refusée, par l'agent. Sans texte : l'interface
 *  choisit le message d'après `kind`. Le rôle insuffisant (`LinkFailure::Forbidden`) et le poste non
 *  reconnu (`LinkFailure::NotRecognized`) sont des échecs typés, pas des refus.
 */
export type AttackModeRefusal = 
/**  Le mot de passe actuel est faux. */
{ kind: "wrong_password" } | 
/**  Trop d'essais de mot de passe : réessayer plus tard. */
{ kind: "too_many_attempts"; retry_after_s: number } | 
/**  L'agent est saturé : réessayer dans un instant. */
{ kind: "busy" } | 
/**
 *  L'élévation de 5 minutes s'est fermée côté agent et le mot de passe n'était pas dans la requête
 *  (jamais le cas du mode attaque, qui n'est pas couvert : la fenêtre le redemande quand même).
 */
{ kind: "password_required" } | 
/**  L'agent ne connaît pas cette fonction (agent d'avant le mode attaque). */
{ kind: "unsupported" } | { kind: "session_ended" } | { kind: "session_revoked" } | { kind: "other" };

export type AttackModeStateDto = "off" | "active" | "suspended";

/**
 *  Une entrée du journal. `at` : RFC 3339 en UTC, la source (l'interface l'affiche dans le fuseau du
 *  poste, BR-AUDIT-012). Toute valeur est du texte non fiable (saisi par des tiers).
 */
export type AuditEntryDto = {
	id: number | null,
	at: string,
	account: string | null,
	origin: AuditOriginDto,
	action: string,
	actionLabel: string,
	target: string | null,
	outcome: AuditOutcomeDto,
	reason: string | null,
	repeatCount: number,
};

/**  Issue d'un export : enregistré, ou abandonné dans la boîte de dialogue. */
export type AuditExportDto = {
	/**  `false` : l'utilisateur a fermé la boîte de dialogue, rien n'est écrit. */
	saved: boolean,
	/**  Seules les 10 000 entrées les plus récentes du résultat sont dans le fichier. */
	truncated: boolean,
};

/**  Le filtre demandé par l'interface (BR-AUDIT-014, 015, 016). Dates : secondes depuis l'époque. */
export type AuditFilterDto = {
	accounts: string[],
	kinds: AuditKindDto[],
	outcomes: AuditOutcomeDto[],
	fromS: number | null,
	toS: number | null,
	text: string | null,
};

/**  Type d'action du filtre (liste fermée de la spec). */
export type AuditKindDto = "login_ok" | "login_denied" | "accounts" | "update" | "denied" | 
/**  Gestion des services (HRT-63, HRT-78). */
"services" | 
/**  Droits sur les services : accordé ou retiré depuis le serveur (HRT-77, HRT-78). */
"services_rights";

/**  Une entrée reçue en direct (`link://audit`). */
export type AuditLiveEvent = {
	serverId: string,
	event: AuditEntryDto,
};

/**  D'où vient l'action. */
export type AuditOriginDto = {
	kind: AuditOriginKindDto,
	name: string | null,
	addr: string | null,
	/**  Le texte à afficher, fourni par l'agent. */
	text: string,
};

export type AuditOriginKindDto = "client" | "cli" | "assistant" | "system";

export type AuditOutcomeDto = "ok" | "denied" | "failed";

/**  Une page du journal filtré, de la plus récente à la plus ancienne. */
export type AuditPageDto = {
	events: AuditEntryDto[],
	/**  Curseur de la page suivante (absent à la fin). */
	nextBefore: number | null,
};

export type AvailableDto = {
	version: string,
	/**  Texte brut (jamais du HTML) ; vide si la release n'en porte pas. */
	notes: string,
};

export type BlockedDto = "fingerprint_changed" | "incompatible_agent" | "incompatible_client";

export type CapabilitiesDto = {
	gpu: boolean,
	temps: boolean,
};

export type CpuInfoDto = {
	model: string,
	physicalCores: number | null,
	logicalCores: number,
	frequencyMhz: number | null,
};

/**  Issue d'un retrait de poste. */
export type DeviceRemovalOutcome = 
/**  L'agent a retiré le poste (et fermé ses sessions). */
{ kind: "done" } | { kind: "refused"; refusal: DeviceRemovalRefusal } | 
/**
 *  Le lien est tombé avant la réponse : on ne sait pas, l'action n'est JAMAIS rejouée. L'issue
 *  arrive par `link://operation` sous cet identifiant ; la liste se relit au retour du lien.
 */
{ kind: "unknown"; op_id: string };

/**  Pourquoi un retrait est refusé. Sans texte : l'interface choisit le message d'après `kind`. */
export type DeviceRemovalRefusal = 
/**  Le mot de passe actuel est faux. */
{ kind: "wrong_password" } | 
/**  C'est le poste d'où part la demande : il ne se retire pas depuis lui-même. */
{ kind: "current_device" } | 
/**
 *  Ce PC n'a pas de clé inscrite (client mis à jour sans reconnexion par mot de passe, coffre
 *  sans clé) : il ne peut rien retirer.
 */
{ kind: "no_device_key" } | 
/**  L'agent n'a pas accepté la preuve de la clé (défi périmé ou rejoué, autre poste). */
{ kind: "proof_refused" } | 
/**  Le poste n'existe plus (déjà retiré ailleurs) : la liste se relit. */
{ kind: "not_found" } | 
/**  Trop d'essais de mot de passe : réessayer plus tard. */
{ kind: "too_many_attempts"; retry_after_s: number } | 
/**  L'agent est saturé : réessayer dans un instant. */
{ kind: "busy" } | 
/**  L'agent ne connaît pas cette fonction (agent d'avant la clé d'appareil). */
{ kind: "unsupported" } | 
/**  La session a expiré pendant l'action. */
{ kind: "session_ended" } | 
/**  La session a été fermée. */
{ kind: "session_revoked" } | { kind: "other" };

export type DiskInfoDto = {
	name: string,
	mount: string,
	fs: string | null,
	totalBytes: number | null,
	removable: boolean,
};

export type DiskSampleDto = {
	name: string,
	mount: string,
	usedBytes: number | null,
	totalBytes: number | null,
};

export type DriverDto = "engine" | "supervisor" | "unknown";

export type EngineDto = {
	state: EngineStateDto,
	name: string | null,
	version: string | null,
	minVersion: string,
	agentAccount: string,
	agentIsAdmin: boolean,
	host: HostDto,
	lastReadyAt: string | null,
	checkedAt: string,
	/**  Date de la dernière lecture complète réussie de la liste ; absente si l'agent ne la donne pas. */
	listReadAt: string | null,
	/**  La liste affichée n'est peut-être plus à jour (relecture en échec, conteneurs illisibles, suivi suspendu). */
	listDegraded: boolean,
	/**  Heure de l'agent à la fabrication de la vue (HRT-72) ; absente pour un agent plus ancien. */
	at: string | null,
	/**  Dernier moment où la liste était à jour (HRT-72) ; absent si aucune liste n'a été lue. */
	listCurrentAt: string | null,
};

export type EngineStateDto = "checking" | "ready" | "stopped" | "access_denied" | "unresponsive" | "absent" | "unsupported_engine" | "unsupported_version" | "disabled" | 
/**  Un état que ce client ne connaît pas : l'interface dit « non reconnu », sans deviner. */
"unknown";

/**  La réponse de `reveal_service_env`, dans l'ordre du moteur. */
export type EnvRevealDto = {
	variables: EnvVariableDto[],
};

/**  Une variable révélée (`BR-SVC-009`). Jamais gardée par la coquille : rendue à l'appelant, c'est tout. */
export type EnvVariableDto = {
	name: HiddenText,
	value: HiddenText,
};

/**
 *  Le certificat présenté n'est plus celui qui a été confirmé (BR-CONN-003). Les empreintes sont
 *  en 8 groupes de 4 pour l'affichage ; `presented_hex` est la forme complète à renvoyer pour
 *  l'accepter.
 */
export type FingerprintEvent = {
	serverId: string,
	expected: string,
	presented: string,
	presentedHex: string,
};

export type GpuInfoDto = {
	name: string,
	memoryTotalBytes: number | null,
};

export type GpuLevelsDto = {
	memory: LevelDto,
	temp: LevelDto,
};

export type GpuSampleDto = {
	name: string,
	loadPercent: number | null,
	memoryUsedBytes: number | null,
	memoryTotalBytes: number | null,
	/**  Absente quand la carte n'expose pas sa température (BR-DASH-007). */
	tempC: number | null,
};

/**
 *  Un texte que l'écran montre mais qu'aucune trace ne doit contenir : nom ou valeur d'une variable
 *  d'environnement, argument de la commande de lancement. Sur le fil vers l'interface c'est un simple texte ;
 *  `Debug` ne montre rien (`HiddenText(***)`), il n'y a pas de `Display`.
 */
export type HiddenText = string;

/**
 *  L'heure écoulée avant l'instantané (`link://history`), à 1 échantillon par 10 secondes : le tableau de bord
 *  amorce sa courbe d'une heure dès l'ouverture (BR-DASH-010). Plus ancienne que l'instantané.
 */
export type HistoryEvent = {
	serverId: string,
	history: SampleDto[],
};

export type HostDto = {
	osId: string,
	osLike: string[],
	init: InitDto,
	declarative: boolean,
};

export type ImageDto = {
	/**  Absent : une image sans nom (« image sans nom {identifiant} », `BR-SVC-022`). */
	ref: string | null,
	tag: string | null,
	shortId: string,
};

export type InitDto = "systemd" | "other";

export type InvalidField = "name" | "address" | "port" | "credentials" | "fingerprint" | "other";

export type LevelDto = "normal" | "attention" | "critical";

/**
 *  Niveau d'alerte de chaque mesure d'un échantillon (BR-DASH-003). Mêmes positions que les
 *  listes de l'échantillon (`disks[i]`, `gpus[i]`, `temps[i]`).
 */
export type LevelsDto = {
	cpu: LevelDto,
	mem: LevelDto,
	disks: LevelDto[],
	gpus: GpuLevelsDto[],
	temps: LevelDto[],
};

/**  Échec d'une commande de liaison, sans texte : l'interface choisit le message d'après `kind`. */
export type LinkFailure = 
/**  Adresse injoignable ou délai dépassé. */
{ kind: "unreachable" } | 
/**  Quelque chose répond, mais ce n'est pas un agent Hearth (BR-CONN-012). */
{ kind: "not_agent" } | 
/**  L'agent est trop ancien (BR-CONN-014). */
{ kind: "incompatible_agent" } | 
/**  Le client est trop ancien (BR-CONN-014). */
{ kind: "incompatible_client" } | 
/**  Identifiant ou mot de passe refusé, sans dire lequel (BR-CONN-013). */
{ kind: "invalid_credentials" } | { kind: "too_many_attempts"; retry_after_s: number } | { kind: "fingerprint_changed" } | { kind: "name_taken" } | { kind: "already_exists" } | 
/**  Champ invalide : `name`, `address`, `port` ou `credentials`. */
{ kind: "invalid_input"; field: InvalidField } | { kind: "verification_required" } | { kind: "unknown_server" } | { kind: "storage" } | { kind: "vault" } | 
/**  Le lien n'est pas « Connecté » : rien n'a été envoyé (BR-RESIL-008). */
{ kind: "not_connected" } | 
/**  Le rôle du compte ne suffit pas (le serveur a répondu `FORBIDDEN_ROLE`, BR-AUDIT-001). */
{ kind: "forbidden" } | 
/**
 *  Le rôle suffit, mais le compte n'a pas le droit de gérer les services (`FORBIDDEN_ROLE` avec
 *  `details.missing: "services"`, BR-GRANT-004) : ce n'est PAS un refus de rôle, l'interface ne dit
 *  jamais « administrateur » (BR-GRANT-014) et relit son droit (BR-GRANT-011).
 */
{ kind: "missing_services_right" } | 
/**  Le suivi de l'action n'a pas pu être écrit sur le disque : l'action n'a PAS été lancée. */
{ kind: "tracking_unavailable" } | 
/**  Le disque est trop lent pour écrire le suivi à temps : l'action n'a PAS été lancée. */
{ kind: "tracking_slow" } | 
/**
 *  Ce PC n'a pas de clé inscrite (ou l'agent n'a pas reconnu la preuve) : un acte qui exige la
 *  preuve de la clé (activer ou désactiver le mode attaque, Q14 point 3) n'est pas possible
 *  d'ici. Quand elle est rendue sans clé au coffre, rien n'est parti.
 */
{ kind: "not_recognized" } | 
/**
 *  Ce PC a une clé mais l'agent ne donne pas de défi à signer : rien n'est parti (ni mot de passe
 *  ni preuve). Ce n'est pas un serveur injoignable.
 */
{ kind: "device_challenge_unavailable" } | { kind: "internal" };

/**
 *  État du lien d'un serveur (`link://state`). `seq` croît strictement par serveur : l'interface
 *  écarte tout événement dont `seq` n'est pas supérieur au dernier connu.
 */
export type LinkStateDto = {
	serverId: string,
	seq: number,
	state: LinkStateName,
	since: number | null,
	lastContactAt: number | null,
	nextRetryAt: number | null,
	blocked: BlockedDto | null,
	reason: ReasonDto | null,
	failedAttempts: number,
};

export type LinkStateName = "connected" | "reconnecting" | "offline" | "session_expired" | "access_revoked";

export type LoginDto = {
	role: RoleDto,
	username: string,
};

/**  Identité de la machine (BR-DASH-001, 005, 006). */
export type MachineDto = {
	name: string,
	os: OsDto,
	cpu: CpuInfoDto,
	memoryTotalBytes: number | null,
	disks: DiskInfoDto[],
	gpus: GpuInfoDto[],
	capabilities: CapabilitiesDto,
};

export type MemoryDto = {
	usedBytes: number | null,
	totalBytes: number | null,
};

/**  Un échantillon en direct (`link://metrics`, chaque seconde). */
export type MetricsEvent = {
	serverId: string,
	sample: SampleDto,
	levels: LevelsDto,
};

export type MountDto = {
	kind: MountKindDto,
	/**  Dossier du serveur, ou nom du volume géré par le moteur. */
	source: string,
	target: string,
	readOnly: boolean,
};

export type MountKindDto = "folder" | "volume" | "unknown";

export type NetDto = {
	upBytesPerS: number | null,
	downBytesPerS: number | null,
};

export type NoticeEvent = {
	/**  Numéro de l'avis retenu par la coquille (acquittement, dédoublonnage) ; 0 : non retenu. */
	id: number,
	kind: NoticeKind,
	serverId: string | null,
	/**  `SessionsClosed` : l'identifiant de l'administrateur qui a fermé les sessions. */
	by: string | null,
	/**  `SessionsClosed` : quand (RFC 3339, UTC). */
	at: string | null,
};

export type NoticeKind = 
/**  Les suivis d'actions d'un serveur étaient illisibles : vérifie l'état avant de relancer. */
"operations_lost" | 
/**  Un autre compte a fermé les sessions de ce compte (HRT-133, BR-ACCT-019) : `by` et `at`. */
"sessions_closed" | 
/**  L'écoute a pris du retard : des changements ont pu être manqués (états relus). */
"lagged";

export type OperationEventDto = {
	opId: string,
	serverId: string,
	outcome: OutcomeDto,
};

export type OriginDto = "hearth" | "external" | "unknown";

export type OsDto = {
	name: string,
	version: string | null,
	kernel: string | null,
	arch: string,
};

export type OutcomeDto = "done" | "not_executed" | "unknown";

export type PasswordRuleDto = "required" | "min_length" | "digit" | "lowercase" | "uppercase" | "contains_username";

export type PortDto = {
	hostPort: number,
	containerPort: number,
	protocol: ProtocolDto,
	scope: ScopeDto,
};

/**  Première prise de contact : l'empreinte à faire confirmer. */
export type ProbeDto = {
	/**  Forme complète (64 caractères hexadécimaux), à renvoyer à `add_server`. */
	fingerprint: string,
	/**  8 groupes de 4 caractères, pour l'affichage. */
	display: string,
	machineName: string,
	agentVersion: string,
	macAddresses: string[],
};

export type ProtocolDto = "tcp" | "udp" | "sctp" | "unknown";

export type ReasonDto = "no_session" | "expired" | "stored_password_refused" | "user_disconnected" | "revoked";

/**  Le réglage « Demander mon mot de passe » du compte (Q19). */
export type ReauthModeDto = 
/**  Une saisie vaut 5 minutes (défaut). */
"window" | 
/**  À chaque action. */
"each";

/**  Issue du changement de réglage. */
export type ReauthSettingOutcome = { kind: "done"; mode: ReauthModeDto } | { kind: "refused"; refusal: ReauthSettingRefusal } | 
/**  Le lien est tombé avant la réponse : on ne sait pas, l'action n'est JAMAIS rejouée. */
{ kind: "unknown"; op_id: string };

/**  Pourquoi l'agent a refusé le réglage. */
export type ReauthSettingRefusal = { kind: "wrong_password" } | 
/**  L'élévation s'est fermée entre-temps et le mot de passe n'était pas dans la requête. */
{ kind: "password_required" } | { kind: "too_many_attempts"; retry_after_s: number } | { kind: "busy" } | 
/**  L'agent ne connaît pas le réglage (agent d'avant). */
{ kind: "unsupported" } | { kind: "session_ended" } | { kind: "session_revoked" } | { kind: "other" };

/**
 *  L'état de la confirmation des actes pour un serveur : lu de l'agent à l'ouverture d'une fenêtre
 *  (l'interface ne devine pas l'élévation).
 */
export type ReauthStateDto = {
	/**  L'agent annonce la confirmation des actes. Faux : aucun acte ne lui part (agent à mettre à jour). */
	supported: boolean,
	/**  L'agent l'exige (faux tant qu'il ne fait que l'accepter). */
	required: boolean,
	/**  Le réglage du compte. */
	mode: ReauthModeDto,
	/**  Secondes restantes de l'élévation de cette session depuis cette adresse ; 0 sinon. */
	elevatedForS: number,
	/**  Ce PC a une clé d'appareil au coffre pour ce serveur. Faux : aucun acte ne part d'ici. */
	hasDeviceKey: boolean,
};

export type RestartDto = "unless_stopped" | "always" | "on_failure" | "none" | "supervisor" | "unknown";

export type RoleDto = "admin" | "readonly";

/**  Une seconde de la vie de la machine. */
export type SampleDto = {
	/**  Instant de la mesure (millisecondes depuis l'époque). */
	at: number | null,
	uptimeS: number | null,
	cpu: number | null,
	cores: (number | null)[],
	mem: MemoryDto,
	disks: DiskSampleDto[],
	net: NetDto | null,
	gpus: GpuSampleDto[],
	temps: TempDto[],
};

export type ScopeDto = "all" | "local" | "unknown";

/**
 *  Ce que l'agent dit de la session de ce poste : prouvée par la clé d'un poste inscrit, ou non.
 *  `Unknown` : pas encore lu (le message du flux ne le porte pas, seule la lecture le dit).
 */
export type SecurityDeviceDto = "proven" | "none" | "unknown";

/**
 *  L'état de sécurité d'un serveur : charge de `link://security` et de `get_security`. `seq` croît
 *  strictement par serveur : l'interface écarte tout état dont `seq` n'est pas supérieur au dernier
 *  connu.
 */
export type SecurityEvent = {
	serverId: string,
	seq: number,
	alert: AlertDto,
	attackMode: AttackModeDto,
	device: SecurityDeviceDto,
	/**  Ce PC garde une clé d'appareil pour ce serveur (un booléen : la clé elle-même ne sort pas). */
	keyAtHand: boolean,
	/**
	 *  L'agent dit que l'effacement physique des anciennes empreintes de requêtes est en attente (HRT-32,
	 *  ADR-0034) : il ne le dit qu'aux administrateurs, et la dernière lecture fait foi (le flux ne le porte pas).
	 */
	erasurePending: boolean,
};

/**
 *  Lecture de l'état de sécurité : l'état, ou « cette fonction n'existe pas sur ce serveur » (agent
 *  d'avant l'alerte et le mode attaque : l'agent répond `404`).
 */
export type SecurityRead = { kind: "known"; snapshot: SecurityEvent } | { kind: "unsupported" };

/**  Un serveur du carnet, sans secret. */
export type ServerDto = {
	id: string,
	name: string,
	/**  Adresse telle qu'on l'affiche : le port n'apparaît que s'il n'est pas celui par défaut. */
	address: string,
	host: string,
	port: number,
	/**  Numéro de la palette de 8 couleurs (1 à 8). */
	color: number,
	/**  Rôle à la dernière connexion ; lecture seule tant qu'on n'est jamais connecté. */
	role: RoleDto,
	username: string,
	remember: boolean,
};

export type ServersEvent = {
	servers: ServerDto[],
};

export type ServiceDto = {
	key: string,
	name: string,
	origin: OriginDto,
	driver: DriverDto | null,
	unit: string | null,
	removedOnStop: boolean,
	composeProject: string | null,
	state: ServiceStateDto,
	since: string | null,
	createdAt: string | null,
	neverStarted: boolean,
	exitCode: number | null,
	restarts10m: number,
	image: ImageDto,
	ports: PortDto[],
	/**  Ports publiés au-delà de la borne de l'agent, non listés (`BR-SVC-021`). */
	portsOmitted: number,
	hostNetwork: boolean,
	mounts: MountDto[],
	mountsOmitted: number,
	restart: RestartDto,
	/**  Noms des variables (jamais une valeur). Vide aussi pour un service adopté dont le détail est réservé. */
	envNames: HiddenText[],
	envNamesOmitted: number,
	/**  La commande lancée ; `None` : « Commande de l'image ». */
	command: HiddenText[] | null,
	/**  Délai d'arrêt en secondes. */
	graceS: number | null,
	adopted: AdoptionDto | null,
	/**  Service adopté dont la commande et les noms de variables sont réservés à ce compte. */
	detailsReserved: boolean,
};

/**
 *  Le droit « gérer les services » du compte connecté (HRT-78, ADR-0041, BR-GRANT-011), en lecture seule.
 *  `known` faux : l'agent n'annonce pas `service-rights` (BR-GRANT-016), `granted` est alors toujours faux.
 *  `account` : l'identifiant du compte connecté, texte de l'agent (l'interface le valide avant tout affichage).
 */
export type ServiceRightsDto = {
	known: boolean,
	granted: boolean,
	account: string,
};

export type ServiceStateDto = "running" | "stopped" | "starting" | "stopping" | "error" | "restart_loop" | "paused" | "deploying" | "unknown";

export type ServicesEvent = {
	serverId: string,
	/**
	 *  Croît strictement par serveur : l'interface écarte tout événement dont `seq` n'est pas supérieur
	 *  au dernier connu (rejeu à l'abonnement compris).
	 */
	seq: number,
	/**
	 *  Quand (millisecondes depuis l'époque, heure de ce poste) LA LIAISON a reçu la vue du moteur de cet
	 *  état : le repère de l'âge de la liste. Il vient de l'étage qui reçoit le message, donc un état rejoué
	 *  ou relu du disque garde sa vraie date. `None` : inconnue (fichier d'avant ce repère, agent sans la
	 *  capacité) ; l'interface ne la remplace jamais par l'heure à laquelle elle traite l'événement.
	 */
	engineReceivedAt: number | null,
	view: ServicesViewDto,
};

/**  Ce que l'agent dit des services d'un serveur : l'état complet, ou « cet agent ne les gère pas ». */
export type ServicesViewDto = { kind: "supported"; engine: EngineDto; services: ServiceDto[] } | 
/**  Pas de capacité `services` dans `/hello` : ni sujet ni route envoyés à cet agent. */
{ kind: "unsupported"; agentVersion: string };

/**
 *  Réglages locaux, tels que l'interface les voit. Le fait que l'explication de
 *  fermeture ait été montrée reste interne à la coquille.
 */
export type Settings = {
	/**  Lancer Hearth au démarrage de Windows (désactivé par défaut, BR-CLIENT-006). */
	launchAtStartup: boolean,
};

/**
 *  Identité et historique (`link://snapshot`, et lecture `get_dashboard`). `levels` : ceux du
 *  dernier échantillon de `history`, s'il y en a un.
 */
export type SnapshotEvent = {
	serverId: string,
	machine: MachineDto,
	history: SampleDto[],
	levels: LevelsDto | null,
};

export type TempDto = {
	label: string,
	celsius: number | null,
};

/**
 *  Un poste de confiance du compte de la session. Les dates sont celles de l'agent (RFC 3339, UTC) ;
 *  l'interface les met en forme.
 */
export type TrustedDeviceDto = {
	id: string,
	name: string,
	createdAt: string,
	lastProvedAt: string,
	lastAddr: string,
	/**  C'est ce PC : il ne se retire pas depuis lui-même. */
	current: boolean,
};

/**
 *  La liste des postes, ou « cette fonction n'existe pas sur ce serveur » (agent d'avant la clé
 *  d'appareil : l'agent répond `404`).
 */
export type TrustedDevicesDto = { kind: "listed"; devices: TrustedDeviceDto[]; max: number } | { kind: "unsupported" };

/**
 *  Pourquoi la dernière mise à jour demandée n'a pas abouti. La version en cours reste utilisable
 *  dans tous les cas.
 */
export type UpdateFailure = 
/**  BR-UPDATE-009 : coupure ; relançable. */
"interrupted" | 
/**  BR-UPDATE-010 : signature ou contenu refusés. */
"corrupted" | 
/**  Autre échec. */
"failed";

export type UpdatePhase = "idle" | 
/**  Interrogation du flux de versions. */
"checking" | 
/**  Téléchargement de l'installateur (signature vérifiée à la fin, avant toute écriture). */
"downloading" | 
/**  Installateur lancé : le client va se fermer et se relancer. */
"installing";

export type UpdateStateDto = {
	/**  Croît à chaque publication : l'interface écarte tout état plus ancien que le dernier vu. */
	seq: number,
	currentVersion: string,
	phase: UpdatePhase,
	/**  Avancement du téléchargement, 0 à 100 ; absent hors téléchargement. */
	progress: number | null,
	available: AvailableDto | null,
	/**  Le bandeau « Nouvelle version disponible » doit être affiché (BR-UPDATE-003, 006). */
	bannerVisible: boolean,
	/**  Le bandeau reparaît à cette date (« Plus tard »). */
	postponedUntil: number | null,
	/**  Dernière vérification qui a obtenu une réponse (BR-UPDATE-007). */
	lastCheckedAt: number | null,
	/**  La dernière vérification a réussi et rien de plus récent n'existe : « Tu es à jour ». */
	upToDate: boolean,
	failure: UpdateFailure | null,
};

export type UsernameProblemDto = "empty" | "too_short" | "too_long" | "invalid_chars";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

